/* font.h - bitmap font tables (generated by tools/fontgen.py) and text drawing */
#ifndef RBUI_FONT_H
#define RBUI_FONT_H

#include "rbui_names.h"
#include <stddef.h>
#include <stdint.h>

typedef struct {
    uint32_t cp;       /* Unicode code point */
    uint8_t adv;       /* advance in pixels */
    int8_t xoff;       /* bitmap left edge relative to the pen */
    int8_t top;        /* first bitmap row relative to the baseline (negative = above) */
    uint8_t w, h;      /* bitmap size; rows are (w+7)/8 bytes, MSB first */
    uint32_t off;      /* offset into bits */
} rbf_glyph;

typedef struct {
    const char *name;  /* cname, e.g. "system12" */
    int ascent, descent, cap, xheight;
    int count;
    const rbf_glyph *glyphs;   /* sorted by cp */
    const uint8_t *bits;
    int levels;        /* 0: 1-bit rows (MSB first); 1: a byte per pixel, coverage 0..16
                          (Mac OS 9 smoothed text, from the Platinum bundle; assets.c) */
} rbf_font;

extern const rbf_font *const rbui_font_table[];   /* NULL-terminated, fonts_data.c */

/* Font by cname (a Platinum bundle font when loaded); falls back to the first font in the table. */
const rbf_font *rbf_get(const char *name);
const rbf_font *assets_font(const char *name);   /* assets.c; NULL if not loaded */

/* Decode one UTF-8 code point at s[*i] (i < len), advancing *i. Invalid or
 * truncated sequences decode as U+FFFD and advance one byte. */
uint32_t rbf_utf8_next(const char *s, size_t len, size_t *i);
/* Byte offset of the previous code point start before i (0 if none). */
size_t rbf_utf8_prev(const char *s, size_t i);
/* Encode cp into out (>= 4 bytes); returns the byte count. */
int rbf_utf8_put(uint32_t cp, char *out);

const rbf_glyph *rbf_find(const rbf_font *f, uint32_t cp);   /* NULL if absent */
int rbf_advance(const rbf_font *f, uint32_t cp);             /* incl. replacement */
int rbf_width(const rbf_font *f, const char *s, size_t len);

#endif
